#include <bits/stdc++.h>
#include <atcoder/dsu>
using namespace std;
using ll = long long;
static constexpr ll inf = 2e18;

int main() {
    int n, m, k;
    cin >> n >> m >> k;
    vector<tuple<int, int, int>> edges(m);
    vector<int> a(k), b(k);
    for (int i = 0; i < m; ++i) {
        int u, v, w;
        cin >> u >> v >> w;
        u--, v--;
        edges[i] = {w, u, v};
    }
    for (int i = 0; i < k; ++i) cin >> a[i];
    for (int i = 0; i < k; ++i) cin >> b[i];

    vector<int> cnt_a(n), cnt_b(n); // 各連結成分の A の個数, Bの個数
    for (int i = 0; i < k; ++i) {
        cnt_a[a[i] - 1]++;
        cnt_b[b[i] - 1]++;
    }
    sort(edges.begin(), edges.end());
    long long ans = 0;
    atcoder::dsu d(n);
    for (int i = 0; i < m; ++i) {
        auto [c, u, v] = edges[i];
        if (d.same(u, v)) continue; //すでに連結ならば無視する
        int ru = d.leader(u), rv = d.leader(v);
        d.merge(u, v);
        int new_root = d.leader(u);
        cnt_a[new_root] = cnt_a[ru] + cnt_a[rv];
        cnt_b[new_root] = cnt_b[ru] + cnt_b[rv];
        ans += 1LL * c * min(cnt_a[new_root], cnt_b[new_root]); //あるだけペアを作る
        const int e = min(cnt_a[new_root], cnt_b[new_root]);
        cnt_a[new_root] -= e;
        cnt_b[new_root] -= e;
    }

    cout << ans << endl;
}
